const ticket = $('get_case_info').item.json.ticket;
if (!ticket || !/^\d+$/.test(String(ticket.id || ''))) throw new Error('Zendesk ticket id missing');
const status = String(ticket.status || '').trim().toLowerCase();
if (!['new','open','pending','hold','solved','closed'].includes(status)) throw new Error('Invalid source ticket status');
const source = String(ticket.updated_at || '').trim();
if (!/(Z|[+-]\d{2}:\d{2})$/.test(source) || !Number.isFinite(Date.parse(source))) throw new Error('Valid source updated_at with timezone required');
const version = new Date(source).toISOString();
const requester = ticket.requester || {};
const fields = Array.isArray(ticket.custom_fields) ? Object.fromEntries(ticket.custom_fields.map(f => [String(f.id), f.value])) : (ticket.custom_fields || {});
return {json: {schema_version:'automation-intake-v1',event_id:'zendesk:automation.preproduction:ticket:'+ticket.id+':updated:'+version+':'+status,event_type:'ticket.updated',occurred_at:version,ticket:{id:String(ticket.id),status,subject:String(ticket.subject || ''),description:String(ticket.description || ''),requester:{id:ticket.requester_id == null ? null : String(ticket.requester_id),name:requester.name || null,email:requester.email || null,role:'end-user',is_agent:false},tags:Array.isArray(ticket.tags)?ticket.tags:[],custom_fields:fields,updated_at:version}}};
